            return false;
        }
        clearError(input, 'fullName-error');
        return true;
    };

    const validateEmail = () => {
        const input = document.getElementById('email');
        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        if (input.value.trim() === '') {
            showError(input, 'email-error', 'Email address is required.');
            return false;
        } else if (!emailRegex.test(input.value)) {
            showError(input, 'email-error', 'Please enter a valid email address.');
            return false;
        }
        clearError(input, 'email-error');
        return true;
    };

    const validatePhone = () => {
        const input = document.getElementById('phone');
        // Allows variations of (123) 456-7890, 123-456-7890, 1234567890, +1 123 456 7890
        const phoneRegex = /^[\+]?[(]?[0-9]{3}[)]?[-\s\.]?[0-9]{3}[-\s\.]?[0-9]{4,6}$/;

        if (input.value.trim() !== '' && !phoneRegex.test(input.value.trim())) {
            showError(input, 'phone-error', 'Please enter a valid phone number format.');
            return false;
        }
        clearError(input, 'phone-error');
        return true;
    };

    form.addEventListener('submit', (e) => {
        e.preventDefault();

        const isNameValid = validateFullName();
        const isEmailValid = validateEmail();
        const isPhoneValid = validatePhone();

        if (isNameValid && isEmailValid && isPhoneValid) {
            alert('Form submitted successfully!');
            form.reset();
            // Clear all validations
            clearError(document.getElementById('fullName'), 'fullName-error');
            clearError(document.getElementById('email'), 'email-error');
            clearError(document.getElementById('phone'), 'phone-error');
        }
    });

    // Real-time validation
    document.getElementById('fullName').addEventListener('blur', validateFullName);
    document.getElementById('email').addEventListener('blur', validateEmail);
    document.getElementById('phone').addEventListener('blur', validatePhone);
});
